dtsPropsFor.Board:
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
items: Item[];
selectedId: string | null;
onSelect: (id: string) => void;
onMove: (id: string, to: { status: string; position?: MovePosition }) => void;
/** Keyboard drag equivalent: move one stage left (-1) or right (+1). */
onMoveRelative: (id: string, dir: -1 | 1) => void;
onQuickAdd: (input: CreateItemInput) => void;
/** Native right-click menu for a card. */
onContext: (item: Item) => void;
/** Ids with a live blocker — compute with blockedIds(items, lastStageId), read per card as a boolean. */
blocked: Set<string>;
/** Ids with a background agent dispatch in flight. */
dispatching?: Set<string>;
/** Card density: "compact" tightens padding/gaps. */
density?: "comfortable" | "compact";

dtsPropsFor.FilterBar:
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
/** Current view items (unfiltered) — assignee/label option lists are derived from them. */
items: Item[];
search: string;
onSearch: (q: string) => void;
/** { area?: string (undefined = all, "" = no area); priority?: string; assignee?: string; label?: string } */
filters: Filters;
onFilters: (f: Filters) => void;
searchRef?: React.RefObject<HTMLInputElement>;

dtsPropsFor.ArchivedList:
/** Archived items only (item.archived === true). */
items: Item[];
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
selectedId: string | null;
onSelect: (id: string) => void;
onRestore: (id: string) => Promise<void>;
onDelete: (id: string) => Promise<void>;

dtsPropsFor.Editor:
item: Item;
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
/** All items — feeds label/link suggestions and [[wiki]] autocomplete. */
items: Item[];
/** Every known item id — resolves [[TICK-001]] links in the markdown preview. */
knownIds: Set<string>;
/** Bumped on every on-disk change so open documents can re-sync. */
changeSignal: number;
onClose: () => void;
onNavigate: (id: string) => void;
/** Saves a diff patch; resolves with the item as written to disk. */
onSave: (patch: UpdateItemPatch) => Promise<Item>;
/** Reports dirty-state changes so the host can guard against losing edits. */
onDirtyChange?: (dirty: boolean) => void;

dtsPropsFor.Settings:
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
items: Item[];
theme: "dark" | "light" | "system";
notifications: boolean;
preferences: { cardDensity: "comfortable" | "compact"; confirmOnDelete: boolean; defaultPriority: string; defaultArea: string };
onSaveBoard: (next: BoardConfig) => Promise<void>;
onSetTheme: (theme: "dark" | "light" | "system") => void;
onSetNotifications: (on: boolean) => void;
onSetPreferences: (patch: Partial<{ cardDensity: "comfortable" | "compact"; confirmOnDelete: boolean; defaultPriority: string; defaultArea: string }>) => void;
onClose: () => void;

dtsPropsFor.TicketCreate:
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
items: Item[];
/** Preferred initial area/priority; used only when on this board. */
defaultArea?: string;
defaultPriority?: string;
onClose: () => void;
/** Create the ticket; resolves with the created item, or null on failure (dialog stays open). */
onCreate: (input: CreateItemInput) => Promise<Item | null>;

dtsPropsFor.Standup:
/** The board config (statuses/areas/priorities/idPrefixes, optional docs + deployment) — see README "Data shapes". */
board: BoardConfig;
items: Item[];
/** The open project's folder name — the report's "### Board: <name>". */
projectName: string;
/** Bumped on every on-disk change; keys the activity/warnings fetch. */
changeSignal: number;
onSelect: (id: string) => void;
